        /// <summary>
        /// Add product options to cart with an existing order line.
        /// </summary>
        /// <remarks>
        /// This endpoint allows adding additional product options like engraving, customizations or additional services to an existing product in the cart.
        /// <br/>&lt;br /&gt;&lt;br /&gt;
        /// <br/>Below you'll find a sample request for adding two product options (engraving and font type) to a cart with id C1234, to order line with LineItemId "a43707ab-1ebf-4114-8c48-eb0374932a4c", which in this case is a diamond ring.
        /// <br/>&lt;br /&gt;
        /// <br/>The product options "P3" and "P5" should be valid SKUs for products in Omnium, with product type set to &lt;code&gt;ProductOption&lt;/code&gt;.
        /// <br/>            
        /// <br/>    POST /api/carts/AddProductOptionsItemToCart
        /// <br/>    {
        /// <br/>        {
        /// <br/>            "cartId": "C1234", // The unique identifier of the cart
        /// <br/>            "parentLineItemId": "a43707ab-1ebf-4114-8c48-eb0374932a4c", // The ID of the existing order line to which product options are added
        /// <br/>            "productOptions": [
        /// <br/>                {
        /// <br/>                    "skuId": "P3", // SKU ID of the product option
        /// <br/>                    "title": "Font type", // Name of the product option
        /// <br/>                    "value": "Big and bold" // The selected option value
        /// <br/>                    "price": 199 // Optional: If you do not et the price in the request, the price will be fetched from the product in Omnium
        /// <br/>                },
        /// <br/>                {
        /// <br/>                    "skuId": "P5",
        /// <br/>                    "title": "Engraving",
        /// <br/>                    "value": "omnium4ever"
        /// <br/>                }
        /// <br/>            ]
        /// <br/>        }
        /// <br/>    }
        /// <br/>            
        /// <br/>This would add two additional order lines to the cart, which would result in a diamond ring engraved with "omnium4ever" with font type "Big and bold". 💍
        /// <br/>&lt;br /&gt;
        /// </remarks>
        /// <returns>Item is added and updated cart is returned</returns>
        /// <exception cref="OmniumApiException">A server side error occurred.</exception>
        System.Threading.Tasks.Task<SwaggerResponse> CartAddProductOptionsItemToCartAsync(OmniumAddProductOptionsRequest body);

